export const snakeTime=ms=>{const s=Math.floor(ms/1000);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');};
export function snakeLeaders(entries){const members=new Map();for(const r of Array.isArray(entries)?entries:[]){if(!r||typeof r.userId!=='string'||!r.userId||typeof r.name!=='string'||!r.name.trim()||!Number.isSafeInteger(r.score)||r.score<=0||r.score>3960||r.score%10||!Number.isSafeInteger(r.elapsedMs)||r.elapsedMs<85||r.elapsedMs>86400000||!Number.isFinite(r.at))continue;const old=members.get(r.userId);if(!old||compare(r,old)<0)members.set(r.userId,r);}return[...members.values()].sort(compare).slice(0,30);}
const compare=(a,b)=>b.score-a.score||a.elapsedMs-b.elapsedMs||a.at-b.at||a.userId.localeCompare(b.userId);
