 function tick(now){frame=0;if(!alive()||phase!=='playing'||!dialog.open)return;const delta=now-lastFrame;lastFrame=now;if(delta>1000){pause();return;}accumulator+=delta;while(accumulator>=game.interval){accumulator-=game.interval;const outcome=game.step();if(outcome.ate){controls();$('#sn-announcer').textContent=game.score+'점';}if(outcome.over){change('over');$('#sn-announcer').textContent='게임 종료. '+game.score+'점.';void save(game.snapshot(run.id,clock.elapsed));return;}}paint(now);time();frame=requestAnimationFrame(tick);}
