 dialog.addEventListener('keydown',event=>{if($('#sn-confirm').open||event.ctrlKey||event.metaKey||event.altKey)return;const direction=({ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',a:'left',d:'right',w:'up',s:'down'})[event.key.length===1?event.key.toLowerCase():event.key];if(direction){event.preventDefault();if(!event.repeat)steer(direction);}else if(event.code==='Space'&&event.target===field){event.preventDefault();phase==='playing'?pause():resume();}});
